// n8n · nœud Code "Calculer les KPI" (Run Once for All Items)
// Lit les 5 nœuds "Lire …" et produit { sujet, html } au style Loodi-mate

// ---------- Données ----------
const rows = (name) =>
  $(name).all().filter((i) => i.json.id).map((i) => i.json.fields ?? i.json);

const joueurs = rows('Lire Joueurs');
const parties = rows('Lire Parties');
const participations = rows('Lire Participations');
const evenements = rows('Lire Événements');
const visiteurs = rows('Lire Visiteurs souvenir');

const num = (v) => (Array.isArray(v) ? Number(v[0]) : Number(v));
const col = (list, f) => list.map((r) => num(r[f])).filter((v) => !Number.isNaN(v));
const avg = (a) => (a.length ? a.reduce((s, x) => s + x, 0) / a.length : null);
const sum = (a) => a.reduce((s, x) => s + x, 0);
const median = (a) => {
  if (!a.length) return null;
  const s = [...a].sort((x, y) => x - y);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};
const ilYa7j = Date.now() - 7 * 24 * 3600 * 1000;
const recent = (d) => d && new Date(d).getTime() >= ilYa7j;

// ---------- KPI ----------
const onboardes = joueurs.filter((j) => num(j['Filtre · Onboardé']) === 1);
const saisisseurs = joueurs.filter((j) => num(j['Filtre · Saisisseur']) === 1);
const nouveauxOnb = onboardes.filter((j) => recent(j['Onboardé le'])).length;
const nouvelles = parties.filter((p) => recent(p['Créée le'])).length;
const enCours = parties.filter((p) => p['Statut'] === 'en cours').length;

const reutil = avg(col(onboardes, 'H1 · Crée 2+ parties'));
const nbReutil = onboardes.filter((j) => num(j['H1 · Crée 2+ parties']) === 100).length;
const dureeMed = median(col(parties, 'Durée de création (s)'));
const comptees = parties.filter((p) => num(p['Filtre · Créée il y a 24 h+']) === 1);
const terminees = avg(col(comptees, 'H1 · Terminée'));
const nonOnb = avg(col(participations, 'H1 · Participant non onboardé'));

const parAction = (a) => evenements.filter((e) => e['Action'] === a);
const ctaClics = parAction('cta_clic');
const liens = parAction('lien_partage');
const ouvertures = parAction('souvenir_ouvert');
const visiteursUniques = new Set(ouvertures.map((e) => e['ID visiteur'])).size;

const h2 = visiteurs.filter(
  (v) => num(v['Filtre · 1re ouverture il y a 48 h+']) === 1 && num(v['Filtre · Dans le plafond']) === 1
);
const h2Onb = h2.filter((v) => v['Type'] === 'onboardé');
const h2Inv = h2.filter((v) => v['Type'] === 'invité');
const h2Total = avg(col(h2, 'H2 · Rouvre sans renvoi'));
const h2TotalOnb = avg(col(h2Onb, 'H2 · Rouvre sans renvoi'));
const h2TotalInv = avg(col(h2Inv, 'H2 · Rouvre sans renvoi'));
const h2Tout = avg(col(h2, 'H2 · Rouvre (tout)'));

const h3 = avg(col(saisisseurs, 'H3 · Consulte stats 2+ fois'));
const consultations = sum(col(joueurs, 'H3 · Nb consultations stats'));

// ---------- Charte Loodi-mate (@loodi/ui tokens) ----------
// URL publique du logo (PNG, les clients mail ignorent le SVG).
// Ex. 'https://<ton-app>.vercel.app/pwa-192x192.png'. Vide = pastille verte de repli.
const LOGO_URL = '';

const C = {
  bg: '#FAFAF8',          // theme-bg
  surface: '#FFFFFF',     // surface-base
  subtle: '#F2F0EC',      // surface-subtle
  ink: '#1A1A18',         // text-primary
  muted: '#6B6B60',       // text-secondary
  line: '#EAE8E3',        // border-subtle, opaque pour le mail
  mate: '#2E8B57',        // module-mate
  mateStrong: '#267247',  // accent-strong (texte blanc AA)
  mateSoft: '#E6F2EB',
  okFg: '#047857', okBg: '#ECFDF5',
  koFg: '#92400E', koBg: '#FFFBEB',
  naFg: '#6B6B60', naBg: '#F2F0EC',
};
const SANS = "'DM Sans',Inter,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const DISPLAY = "'Playfair Display',Georgia,'Times New Roman',serif";

const pct = (v) => (v === null ? '–' : `${Math.round(v)} %`);
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');

const pill = (etat) => {
  const p = {
    ok: [C.okFg, C.okBg, 'Seuil atteint'],
    ko: [C.koFg, C.koBg, 'Sous le seuil'],
    na: [C.naFg, C.naBg, 'Pas encore de données'],
    info: [C.naFg, C.naBg, 'Indicateur'],
  }[etat];
  return `<span style="display:inline-block;padding:3px 9px;border-radius:999px;background:${p[1]};color:${p[0]};font-size:11px;font-weight:600;white-space:nowrap">${p[2]}</span>`;
};
const etat = (v, ok) => (v === null ? 'na' : ok(v) ? 'ok' : 'ko');

const barre = (v) => {
  if (v === null) return '';
  const w = Math.max(0, Math.min(100, Math.round(v)));
  const plein = w > 0 ? `<td width="${w}%" style="background:${C.mate};height:8px;line-height:8px;font-size:0;border-radius:4px">&nbsp;</td>` : '';
  const vide = w < 100 ? `<td style="background:${C.subtle};height:8px;line-height:8px;font-size:0;border-radius:4px">&nbsp;</td>` : '';
  return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:10px;border-collapse:separate"><tr>${plein}${vide}</tr></table>`;
};

const kpi = ({ label, detail = '', valeur, statut = 'info', progression = null, dernier = false }) => `
<tr><td style="padding:16px 18px;${dernier ? '' : `border-bottom:1px solid ${C.line};`}">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
    <td style="vertical-align:top">
      <div style="font-size:15px;font-weight:600;color:${C.ink}">${esc(label)}</div>
      ${detail ? `<div style="font-size:13px;line-height:1.45;color:${C.muted};margin-top:3px">${esc(detail)}</div>` : ''}
    </td>
    <td style="vertical-align:top;text-align:right;white-space:nowrap;padding-left:12px">
      <div style="font-size:24px;font-weight:700;color:${C.ink};line-height:1.1">${valeur}</div>
      <div style="margin-top:6px">${pill(statut)}</div>
    </td>
  </tr></table>
  ${barre(progression)}
</td></tr>`;

const section = (code, titre, hypothese, lignes) => `
<tr><td style="padding:30px 2px 12px">
  <table role="presentation" cellpadding="0" cellspacing="0"><tr>
    <td style="vertical-align:middle"><span style="display:inline-block;padding:4px 10px;border-radius:8px;background:${C.mateSoft};color:${C.mateStrong};font-size:12px;font-weight:700;letter-spacing:0.04em">${code}</span></td>
    <td style="vertical-align:middle;padding-left:10px;font-family:${DISPLAY};font-size:21px;font-weight:600;color:${C.ink}">${esc(titre)}</td>
  </tr></table>
  <div style="font-size:14px;line-height:1.5;color:${C.muted};margin-top:8px">${esc(hypothese)}</div>
</td></tr>
<tr><td>
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${C.surface};border:1px solid ${C.line};border-radius:18px;border-collapse:separate">
    ${lignes.map((l, i) => kpi({ ...l, dernier: i === lignes.length - 1 })).join('')}
  </table>
</td></tr>`;

const tuile = (valeur, label, delta) => `
<td width="33%" style="padding:0 4px;vertical-align:top">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${C.surface};border:1px solid ${C.line};border-radius:18px;border-collapse:separate">
    <tr><td style="padding:16px 14px">
      <div style="font-family:${DISPLAY};font-size:28px;font-weight:700;color:${C.ink};line-height:1.1">${valeur}</div>
      <div style="font-size:13px;color:${C.muted};margin-top:4px">${esc(label)}</div>
      ${delta ? `<div style="display:inline-block;margin-top:8px;padding:2px 8px;border-radius:999px;background:${C.mateSoft};font-size:12px;font-weight:600;color:${C.mateStrong}">${esc(delta)}</div>` : ''}
    </td></tr>
  </table>
</td>`;

const logo = LOGO_URL
  ? `<img src="${LOGO_URL}" width="52" height="52" alt="Loodi-mate" style="display:block;border:0;border-radius:14px">`
  : `<div style="width:52px;height:52px;border-radius:14px;background:${C.mate};color:#FFFFFF;font-family:${DISPLAY};font-size:26px;font-weight:700;line-height:52px;text-align:center">m</div>`;

const date = new Date().toLocaleDateString('fr-FR', {
  timeZone: 'Europe/Paris', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric',
});

// ---------- Mail ----------
const html = `<!doctype html>
<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;600;700&family=Playfair+Display:wght@600;700&display=swap" rel="stylesheet">
<title>Loodi-mate · Rapport hebdo</title></head>
<body style="margin:0;padding:0;background:${C.bg}">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${C.bg}"><tr><td align="center" style="padding:24px 12px">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;font-family:${SANS};color:${C.ink}">

<tr><td>
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${C.surface};border:1px solid ${C.line};border-radius:18px;border-collapse:separate;border-top:4px solid ${C.mate}">
    <tr><td style="padding:22px 20px">
      <table role="presentation" cellpadding="0" cellspacing="0"><tr>
        <td style="vertical-align:middle">${logo}</td>
        <td style="vertical-align:middle;padding-left:14px">
          <div style="font-size:12px;font-weight:600;letter-spacing:0.06em;text-transform:uppercase;color:${C.mateStrong}">Loodi-mate · Test du MVP</div>
          <div style="font-family:${DISPLAY};font-size:26px;font-weight:600;line-height:1.2;color:${C.ink};margin-top:4px">Rapport hebdo des hypothèses</div>
        </td>
      </tr></table>
      <div style="font-size:14px;color:${C.muted};margin-top:14px">${esc(date)} · cumul depuis le début du test</div>
    </td></tr>
  </table>
</td></tr>

<tr><td style="padding-top:12px">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 -4px"><tr>
    ${tuile(`${onboardes.length}<span style="font-family:${SANS};font-size:14px;color:${C.muted};font-weight:600"> / 8–12</span>`, 'joueurs onboardés', nouveauxOnb ? `+${nouveauxOnb} cette semaine` : '')}
    ${tuile(parties.length, 'parties enregistrées', nouvelles ? `+${nouvelles} cette semaine` : '')}
    ${tuile(saisisseurs.length, 'saisisseurs', '')}
  </tr></table>
</td></tr>

${section('H1', 'Enregistrement', 'Les joueurs enregistrent leurs parties si la saisie est simple et rapide.', [
  { label: 'Réutilisation', detail: `Onboardés ayant créé 2 parties ou plus (${nbReutil} sur ${onboardes.length}) · seuil 50 %`, valeur: pct(reutil), statut: etat(reutil, (v) => v >= 50), progression: reutil },
  { label: 'Durée médiane de création', detail: 'De "Nouvelle partie" au tap "Créer" · seuil < 60 s', valeur: dureeMed === null ? '–' : `${Math.round(dureeMed)} s`, statut: etat(dureeMed, (v) => v < 60) },
  { label: 'Parties terminées', detail: `Parties créées il y a 24 h ou plus (n = ${comptees.length}) · seuil 90 %`, valeur: pct(terminees), statut: etat(terminees, (v) => v >= 90), progression: terminees },
  { label: 'Participants non onboardés', detail: `Diffusion · ${enCours} partie(s) en cours`, valeur: pct(nonOnb) },
  { label: 'Clics sur "Essayer Loodi-mate"', detail: `Diffusion depuis la vue invité · +${ctaClics.filter((e) => recent(e['Date'])).length} cette semaine`, valeur: ctaClics.length },
])}

${section('H2', 'Souvenirs', 'Les joueurs reviennent d’eux-mêmes consulter leurs souvenirs.', [
  { label: 'Réouverture à 48 h+ sans renvoi', detail: `Onboardés et invités (n = ${h2.length}) · seuil 50 %`, valeur: pct(h2Total), statut: etat(h2Total, (v) => v >= 50), progression: h2Total },
  { label: 'dont joueurs onboardés', detail: `n = ${h2Onb.length} · seuil 50 %`, valeur: pct(h2TotalOnb), statut: etat(h2TotalOnb, (v) => v >= 50), progression: h2TotalOnb },
  { label: 'dont invités du lien', detail: `n = ${h2Inv.length} · seuil 50 %`, valeur: pct(h2TotalInv), statut: etat(h2TotalInv, (v) => v >= 50), progression: h2TotalInv },
  { label: 'Réouverture tout compris', detail: 'Y compris après un renvoi du lien', valeur: pct(h2Tout) },
  { label: 'Partage et consultation', detail: `${liens.length} lien(s) partagé(s) · ${visiteursUniques} visiteur(s) unique(s) · +${ouvertures.filter((e) => recent(e['Date'])).length} ouverture(s) cette semaine`, valeur: ouvertures.length },
])}

${section('H3', 'Statistiques', 'Les joueurs suivent leurs résultats dans la durée.', [
  { label: 'Saisisseurs engagés', detail: `Consultent leurs stats 2 fois ou plus (n = ${saisisseurs.length}) · seuil 50 %`, valeur: pct(h3), statut: etat(h3, (v) => v >= 50), progression: h3 },
  { label: 'Consultations des statistiques', detail: 'Total sur la période', valeur: consultations },
])}

<tr><td style="padding:26px 4px 8px;font-size:12px;line-height:1.55;color:${C.muted}">
  H2 recalculé chaque jour à 6 h par n8n. Effectifs faibles : lire les pourcentages avec leur n.<br>
  Sources : base Airtable "MVP Jedha Loodi mate", interface "Pilotage hypothèses".
</td></tr>

</table>
</td></tr></table>
</body></html>`;

return [{ json: {
  sujet: `Loodi-mate KPI : ${nouvelles} nouvelle(s) partie(s) cette semaine`,
  html,
} }];
